CREATE TABLE "rules_alternative" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "created_at" date NOT NULL, "updated_at" datetime NOT NULL, "comment" text NULL, "lemma" varchar(255) NOT NULL, "word_types" varchar(255) NULL, "is_inspiration" bool NOT NULL, "is_active" bool NOT NULL, "label" varchar(255) NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "rule_id" integer NOT NULL REFERENCES "rules_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "source_id" integer NULL REFERENCES "rules_source" ("id") DEFERRABLE INITIALLY DEFERRED, "lemma_json" text NOT NULL CHECK ((JSON_VALID("lemma_json") OR "lemma_json" IS NULL)), "word_types_json" text NOT NULL CHECK ((JSON_VALID("word_types_json") OR "word_types_json" IS NULL)), "type" varchar(14) NOT NULL, "is_advanced" bool NOT NULL, "pluralization" varchar(13) NOT NULL, "is_placeholder" bool NOT NULL, "is_remove" bool NOT NULL, "language" varchar(2) NOT NULL);
